package main

import (
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
)

// Record is an ordered key-value map preserving insertion order.
type Record struct {
	Keys   []string
	Values []string
}

func NewRecord() *Record {
	return &Record{}
}

func (r *Record) Len() int { return len(r.Keys) }

func (r *Record) indexOf(key string) int {
	for i, k := range r.Keys {
		if k == key {
			return i
		}
	}
	return -1
}

func (r *Record) Has(key string) bool { return r.indexOf(key) >= 0 }

func (r *Record) Get(key string) (string, bool) {
	i := r.indexOf(key)
	if i < 0 {
		return "", false
	}
	return r.Values[i], true
}

func (r *Record) Set(key, value string) {
	i := r.indexOf(key)
	if i >= 0 {
		r.Values[i] = value
		return
	}
	r.Keys = append(r.Keys, key)
	r.Values = append(r.Values, value)
}

func (r *Record) Prepend(key, value string) {
	// If key exists, remove and re-insert at start.
	r.Delete(key)
	r.Keys = append([]string{key}, r.Keys...)
	r.Values = append([]string{value}, r.Values...)
}

func (r *Record) Delete(key string) bool {
	i := r.indexOf(key)
	if i < 0 {
		return false
	}
	r.Keys = append(r.Keys[:i], r.Keys[i+1:]...)
	r.Values = append(r.Values[:i], r.Values[i+1:]...)
	return true
}

func (r *Record) Copy() *Record {
	out := NewRecord()
	out.Keys = append(out.Keys, r.Keys...)
	out.Values = append(out.Values, r.Values...)
	return out
}

func (r *Record) Rename(old, new string) {
	i := r.indexOf(old)
	if i < 0 {
		return
	}
	// If the new name already exists elsewhere, the old record is replaced.
	j := r.indexOf(new)
	if j >= 0 && j != i {
		// Miller's rename collapses: the value at old replaces value at new, remove old.
		r.Values[j] = r.Values[i]
		r.Keys = append(r.Keys[:i], r.Keys[i+1:]...)
		r.Values = append(r.Values[:i], r.Values[i+1:]...)
		return
	}
	r.Keys[i] = new
}

// --- Type inference utilities used in JSON output ---

var intRe = regexp.MustCompile(`^-?\d+$`)
var floatRe = regexp.MustCompile(`^-?(\d+\.\d*|\.\d+|\d+)([eE][-+]?\d+)?$`)

// IsInt returns true if s can be represented as a (decimal) integer in the
// style Miller uses for type inference.
func IsInt(s string) bool {
	if s == "" {
		return false
	}
	if !intRe.MatchString(s) {
		return false
	}
	_, err := strconv.ParseInt(s, 10, 64)
	return err == nil
}

func IsFloat(s string) bool {
	if s == "" || IsInt(s) {
		return false
	}
	if !floatRe.MatchString(s) {
		return false
	}
	_, err := strconv.ParseFloat(s, 64)
	return err == nil
}

// NumericCompare returns -1, 0, 1 if both strings are numeric; otherwise
// falls back to a non-numeric interpretation with boolean indicator.
func NumericCompare(a, b string) (int, bool) {
	if IsInt(a) && IsInt(b) {
		x, _ := strconv.ParseInt(a, 10, 64)
		y, _ := strconv.ParseInt(b, 10, 64)
		if x < y {
			return -1, true
		}
		if x > y {
			return 1, true
		}
		return 0, true
	}
	af, ae := strconv.ParseFloat(a, 64)
	bf, be := strconv.ParseFloat(b, 64)
	if ae == nil && be == nil {
		if af < bf {
			return -1, true
		}
		if af > bf {
			return 1, true
		}
		return 0, true
	}
	return 0, false
}

// FormatFloat produces Miller-like float output (no trailing ".0").
func FormatFloat(f float64) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, +1) {
		return "+Inf"
	}
	if math.IsInf(f, -1) {
		return "-Inf"
	}
	// Try integer form if possible.
	if f == math.Trunc(f) && !math.IsInf(f, 0) && math.Abs(f) < 1e16 {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

// JoinFields produces a comma-separated list.
func JoinFields(xs []string) string {
	return strings.Join(xs, ",")
}

func parseCommaList(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

// AsError formats a Miller-style command error.
func mlrError(format string, args ...interface{}) error {
	return fmt.Errorf(format, args...)
}
GOEOF
