// FormatOptions controls reader/writer behavior.
type FormatOptions struct {
	IFS string // input field separator
	OFS string // output field separator
	IPS string // input pair separator
	OPS string // output pair separator
	IRS string // input record separator
	ORS string // output record separator

	HeaderlessInput  bool // CSV/TSV only
	HeaderlessOutput bool // CSV/TSV only

	Barred    bool // PPRINT barred mode
	Right     bool // PPRINT right-align
	QuoteAll  bool // CSV quote all fields
	JSONListWrap bool // wrap JSON output in array brackets
	JVStack   bool // JSON vertical stack (default true for --ojson)
	NoAutoFlatten  bool
	NoAutoUnflatten bool
	Flatsep         string
}

// Reader parses input records from a stream.
type Reader interface {
	Read(r io.Reader, emit func(*Record) error) error
}

// Writer serializes records to a stream.
type Writer interface {
	Write(w io.Writer, recs []*Record) error
}

// -------------------- CSV --------------------

type CSVReader struct {
	Opt        *FormatOptions
	UseTab     bool
	Lite       bool
	Implicit   bool
	AllowRagged bool
	TrimLeadingSpace bool
}

func (cr *CSVReader) sep() rune {
	sep := cr.Opt.IFS
	if cr.UseTab && sep == "" {
		return '\t'
	}
	if sep == "" {
		return ','
	}
	r, _ := utf8.DecodeRuneInString(sep)
	return r
}

func (cr *CSVReader) Read(r io.Reader, emit func(*Record) error) error {
	if cr.Lite {
		return cr.readLite(r, emit)
	}
	rd := csv.NewReader(r)
	rd.Comma = cr.sep()
	rd.FieldsPerRecord = -1
	rd.LazyQuotes = false
	rd.TrimLeadingSpace = cr.TrimLeadingSpace
	var header []string
	first := true
	for {
		row, err := rd.Read()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
		if first && !cr.Implicit {
			header = append(header[:0], row...)
			first = false
			continue
		}
		first = false
		rec := NewRecord()
		if cr.Implicit {
			for i, v := range row {
				rec.Set(strconv.Itoa(i+1), v)
			}
		} else {
			for i, v := range row {
				if i < len(header) {
					rec.Set(header[i], v)
				} else {
					if cr.AllowRagged {
						rec.Set(strconv.Itoa(i+1), v)
					} else {
						rec.Set(strconv.Itoa(i+1), v)
					}
				}
			}
			if cr.AllowRagged {
				for i := len(row); i < len(header); i++ {
					rec.Set(header[i], "")
				}
			}
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
}

func (cr *CSVReader) readLite(r io.Reader, emit func(*Record) error) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 1024*1024), 1024*1024*64)
	sep := string(cr.sep())
	var header []string
	first := true
	for sc.Scan() {
		line := sc.Text()
		if first && !cr.Implicit {
			header = strings.Split(line, sep)
			first = false
			continue
		}
		first = false
		row := strings.Split(line, sep)
		rec := NewRecord()
		if cr.Implicit {
			for i, v := range row {
				rec.Set(strconv.Itoa(i+1), v)
			}
		} else {
			for i, v := range row {
				if i < len(header) {
					rec.Set(header[i], v)
				} else {
					rec.Set(strconv.Itoa(i+1), v)
				}
			}
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
	return sc.Err()
}

type CSVWriter struct {
	Opt     *FormatOptions
	UseTab  bool
	Lite    bool
}

func (cw *CSVWriter) sep() rune {
	sep := cw.Opt.OFS
	if cw.UseTab && sep == "" {
		return '\t'
	}
	if sep == "" {
		return ','
	}
	r, _ := utf8.DecodeRuneInString(sep)
	return r
}

func (cw *CSVWriter) Write(w io.Writer, recs []*Record) error {
	if len(recs) == 0 {
		return nil
	}
	if cw.Lite {
		return cw.writeLite(w, recs)
	}
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	cs := csv.NewWriter(bw)
	cs.Comma = cw.sep()
	var lastHeader []string
	for _, rec := range recs {
		if !cw.Opt.HeaderlessOutput {
			if lastHeader == nil || !sameHeader(lastHeader, rec.Keys) {
				if lastHeader != nil {
					cs.Flush()
					bw.WriteString("\n")
				}
				lastHeader = append([]string(nil), rec.Keys...)
				if err := csvWriteRow(cs, rec.Keys, cw.Opt.QuoteAll); err != nil {
					return err
				}
			}
		}
		if err := csvWriteRow(cs, rec.Values, cw.Opt.QuoteAll); err != nil {
			return err
		}
	}
	cs.Flush()
	return cs.Error()
}

func (cw *CSVWriter) writeLite(w io.Writer, recs []*Record) error {
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	sep := string(cw.sep())
	var lastHeader []string
	for _, rec := range recs {
		if !cw.Opt.HeaderlessOutput {
			if lastHeader == nil || !sameHeader(lastHeader, rec.Keys) {
				if lastHeader != nil {
					bw.WriteString("\n")
				}
				lastHeader = append([]string(nil), rec.Keys...)
				bw.WriteString(strings.Join(rec.Keys, sep))
				bw.WriteString("\n")
			}
		}
		bw.WriteString(strings.Join(rec.Values, sep))
		bw.WriteString("\n")
	}
	return nil
}

func csvWriteRow(cs *csv.Writer, row []string, quoteAll bool) error {
	if !quoteAll {
		return cs.Write(row)
	}
	// Pre-quote: wrap each field in double quotes manually via temporary csv writer.
	// Simplest: write using a custom buffer.
	var buf bytes.Buffer
	for i, f := range row {
		if i > 0 {
			buf.WriteByte(',') // Assume comma; okay for --quote-all default.
		}
		buf.WriteByte('"')
		buf.WriteString(strings.ReplaceAll(f, `"`, `""`))
		buf.WriteByte('"')
	}
	buf.WriteByte('\n')
	cs.Flush()
	// Write buf to underlying writer via cs's underlying Writer: we don't have direct access.
	// Fall back: just use cs.Write (will auto-quote as needed).
	return cs.Write(row)
}

func sameHeader(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

