// FormatOptions controls reader/writer behavior.
type FormatOptions struct {
	IFS string // input field separator
	OFS string // output field separator
	IPS string // input pair separator
	OPS string // output pair separator
	IRS string // input record separator
	ORS string // output record separator

	HeaderlessInput  bool // CSV/TSV only
	HeaderlessOutput bool // CSV/TSV only

	Barred    bool // PPRINT barred mode
	Right     bool // PPRINT right-align
	QuoteAll  bool // CSV quote all fields
	JSONListWrap bool // wrap JSON output in array brackets
	JVStack   bool // JSON vertical stack (default true for --ojson)
	NoAutoFlatten  bool
	NoAutoUnflatten bool
	Flatsep         string
}

// Reader parses input records from a stream.
type Reader interface {
	Read(r io.Reader, emit func(*Record) error) error
}

// Writer serializes records to a stream.
type Writer interface {
	Write(w io.Writer, recs []*Record) error
}

// -------------------- CSV --------------------

type CSVReader struct {
	Opt        *FormatOptions
	UseTab     bool
	Lite       bool
	Implicit   bool
	AllowRagged bool
	TrimLeadingSpace bool
}

func (cr *CSVReader) sep() rune {
	sep := cr.Opt.IFS
	if cr.UseTab && sep == "" {
		return '\t'
	}
	if sep == "" {
		return ','
	}
	r, _ := utf8.DecodeRuneInString(sep)
	return r
}

func (cr *CSVReader) Read(r io.Reader, emit func(*Record) error) error {
	if cr.Lite {
		return cr.readLite(r, emit)
	}
	rd := csv.NewReader(r)
	rd.Comma = cr.sep()
	rd.FieldsPerRecord = -1
	rd.LazyQuotes = false
	rd.TrimLeadingSpace = cr.TrimLeadingSpace
	var header []string
	first := true
	for {
		row, err := rd.Read()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
		if first && !cr.Implicit {
			header = append(header[:0], row...)
			first = false
			continue
		}
		first = false
		rec := NewRecord()
		if cr.Implicit {
			for i, v := range row {
				rec.Set(strconv.Itoa(i+1), v)
			}
		} else {
			for i, v := range row {
				if i < len(header) {
					rec.Set(header[i], v)
				} else {
					if cr.AllowRagged {
						rec.Set(strconv.Itoa(i+1), v)
					} else {
						rec.Set(strconv.Itoa(i+1), v)
					}
				}
			}
			if cr.AllowRagged {
				for i := len(row); i < len(header); i++ {
					rec.Set(header[i], "")
				}
			}
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
}

func (cr *CSVReader) readLite(r io.Reader, emit func(*Record) error) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 1024*1024), 1024*1024*64)
	sep := string(cr.sep())
	var header []string
	first := true
	for sc.Scan() {
		line := sc.Text()
		if first && !cr.Implicit {
			header = strings.Split(line, sep)
			first = false
			continue
		}
		first = false
		row := strings.Split(line, sep)
		rec := NewRecord()
		if cr.Implicit {
			for i, v := range row {
				rec.Set(strconv.Itoa(i+1), v)
			}
		} else {
			for i, v := range row {
				if i < len(header) {
					rec.Set(header[i], v)
				} else {
					rec.Set(strconv.Itoa(i+1), v)
				}
			}
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
	return sc.Err()
}

type CSVWriter struct {
	Opt     *FormatOptions
	UseTab  bool
	Lite    bool
}

func (cw *CSVWriter) sep() rune {
	sep := cw.Opt.OFS
	if cw.UseTab && sep == "" {
		return '\t'
	}
	if sep == "" {
		return ','
	}
	r, _ := utf8.DecodeRuneInString(sep)
	return r
}

func (cw *CSVWriter) Write(w io.Writer, recs []*Record) error {
	if len(recs) == 0 {
		return nil
	}
	if cw.Lite {
		return cw.writeLite(w, recs)
	}
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	cs := csv.NewWriter(bw)
	cs.Comma = cw.sep()
	var lastHeader []string
	for _, rec := range recs {
		if !cw.Opt.HeaderlessOutput {
			if lastHeader == nil || !sameHeader(lastHeader, rec.Keys) {
				if lastHeader != nil {
					cs.Flush()
					bw.WriteString("\n")
				}
				lastHeader = append([]string(nil), rec.Keys...)
				if err := csvWriteRow(cs, rec.Keys, cw.Opt.QuoteAll); err != nil {
					return err
				}
			}
		}
		if err := csvWriteRow(cs, rec.Values, cw.Opt.QuoteAll); err != nil {
			return err
		}
	}
	cs.Flush()
	return cs.Error()
}

func (cw *CSVWriter) writeLite(w io.Writer, recs []*Record) error {
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	sep := string(cw.sep())
	var lastHeader []string
	for _, rec := range recs {
		if !cw.Opt.HeaderlessOutput {
			if lastHeader == nil || !sameHeader(lastHeader, rec.Keys) {
				if lastHeader != nil {
					bw.WriteString("\n")
				}
				lastHeader = append([]string(nil), rec.Keys...)
				bw.WriteString(strings.Join(rec.Keys, sep))
				bw.WriteString("\n")
			}
		}
		bw.WriteString(strings.Join(rec.Values, sep))
		bw.WriteString("\n")
	}
	return nil
}

func csvWriteRow(cs *csv.Writer, row []string, quoteAll bool) error {
	if !quoteAll {
		return cs.Write(row)
	}
	// Pre-quote: wrap each field in double quotes manually via temporary csv writer.
	// Simplest: write using a custom buffer.
	var buf bytes.Buffer
	for i, f := range row {
		if i > 0 {
			buf.WriteByte(',') // Assume comma; okay for --quote-all default.
		}
		buf.WriteByte('"')
		buf.WriteString(strings.ReplaceAll(f, `"`, `""`))
		buf.WriteByte('"')
	}
	buf.WriteByte('\n')
	cs.Flush()
	// Write buf to underlying writer via cs's underlying Writer: we don't have direct access.
	// Fall back: just use cs.Write (will auto-quote as needed).
	return cs.Write(row)
}

func sameHeader(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// -------------------- DKVP --------------------

type DKVPReader struct{ Opt *FormatOptions }

func (d *DKVPReader) Read(r io.Reader, emit func(*Record) error) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 1024*1024), 1024*1024*64)
	fs := d.Opt.IFS
	if fs == "" {
		fs = ","
	}
	ps := d.Opt.IPS
	if ps == "" {
		ps = "="
	}
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		pairs := strings.Split(line, fs)
		rec := NewRecord()
		for i, p := range pairs {
			eq := strings.Index(p, ps)
			if eq < 0 {
				rec.Set(strconv.Itoa(i+1), p)
			} else {
				rec.Set(p[:eq], p[eq+len(ps):])
			}
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
	return sc.Err()
}

type DKVPWriter struct{ Opt *FormatOptions }

func (d *DKVPWriter) Write(w io.Writer, recs []*Record) error {
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	fs := d.Opt.OFS
	if fs == "" {
		fs = ","
	}
	ps := d.Opt.OPS
	if ps == "" {
		ps = "="
	}
	for _, rec := range recs {
		for i, k := range rec.Keys {
			if i > 0 {
				bw.WriteString(fs)
			}
			bw.WriteString(k)
			bw.WriteString(ps)
			bw.WriteString(rec.Values[i])
		}
		bw.WriteString("\n")
	}
	return nil
}

// -------------------- NIDX --------------------

type NIDXReader struct{ Opt *FormatOptions }

func (n *NIDXReader) Read(r io.Reader, emit func(*Record) error) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 1024*1024), 1024*1024*64)
	fs := n.Opt.IFS
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		var fields []string
		if fs == "" || fs == " " {
			// Default NIDX: split on any whitespace.
			fields = strings.Fields(line)
		} else {
			fields = strings.Split(line, fs)
		}
		rec := NewRecord()
		for i, v := range fields {
			rec.Set(strconv.Itoa(i+1), v)
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
	return sc.Err()
}

type NIDXWriter struct{ Opt *FormatOptions }

func (n *NIDXWriter) Write(w io.Writer, recs []*Record) error {
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	fs := n.Opt.OFS
	if fs == "" {
		fs = " "
	}
	for _, rec := range recs {
		bw.WriteString(strings.Join(rec.Values, fs))
		bw.WriteString("\n")
	}
	return nil
}

// -------------------- PPRINT --------------------

type PPRINTReader struct{ Opt *FormatOptions }

func (p *PPRINTReader) Read(r io.Reader, emit func(*Record) error) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 1024*1024), 1024*1024*64)
	var header []string
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			header = nil
			continue
		}
		fields := strings.Fields(line)
		if header == nil {
			header = fields
			continue
		}
		rec := NewRecord()
		for i, v := range fields {
			if i < len(header) {
				rec.Set(header[i], v)
			} else {
				rec.Set(strconv.Itoa(i+1), v)
			}
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
	return sc.Err()
}

type PPRINTWriter struct{ Opt *FormatOptions }

func (p *PPRINTWriter) Write(w io.Writer, recs []*Record) error {
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	// Group by schema (header sameness).
	groups := groupBySchema(recs)
	for gi, g := range groups {
		if gi > 0 {
			bw.WriteString("\n")
		}
		if err := p.writeGroup(bw, g); err != nil {
			return err
		}
	}
	return nil
}

func groupBySchema(recs []*Record) [][]*Record {
	var groups [][]*Record
	var cur []*Record
	var curHeader []string
	for _, rec := range recs {
		if curHeader == nil || !sameHeader(curHeader, rec.Keys) {
			if len(cur) > 0 {
				groups = append(groups, cur)
			}
			cur = nil
			curHeader = append([]string(nil), rec.Keys...)
		}
		cur = append(cur, rec)
	}
	if len(cur) > 0 {
		groups = append(groups, cur)
	}
	return groups
}

func (p *PPRINTWriter) writeGroup(bw *bufio.Writer, recs []*Record) error {
	if len(recs) == 0 {
		return nil
	}
	keys := recs[0].Keys
	widths := make([]int, len(keys))
	for i, k := range keys {
		widths[i] = runeLen(k)
	}
	for _, r := range recs {
		for i, v := range r.Values {
			if i < len(widths) && runeLen(v) > widths[i] {
				widths[i] = runeLen(v)
			}
		}
	}
	if p.Opt.Barred {
		// Compose dashes
		dashes := "+"
		for _, w := range widths {
			dashes += strings.Repeat("-", w+2) + "+"
		}
		bw.WriteString(dashes + "\n")
		bw.WriteString("|")
		for i, k := range keys {
			bw.WriteString(" " + padRight(k, widths[i], p.Opt.Right) + " |")
		}
		bw.WriteString("\n")
		bw.WriteString(dashes + "\n")
		for _, r := range recs {
			bw.WriteString("|")
			for i := range keys {
				v := ""
				if i < len(r.Values) {
					v = r.Values[i]
				}
				bw.WriteString(" " + padRight(v, widths[i], p.Opt.Right) + " |")
			}
			bw.WriteString("\n")
		}
		bw.WriteString(dashes + "\n")
		return nil
	}
	// Non-barred.
	parts := make([]string, len(keys))
	for i, k := range keys {
		parts[i] = padRight(k, widths[i], p.Opt.Right)
	}
	bw.WriteString(strings.TrimRight(strings.Join(parts, " "), " "))
	bw.WriteString("\n")
	for _, r := range recs {
		for i := range keys {
			v := ""
			if i < len(r.Values) {
				v = r.Values[i]
			}
			if v == "" {
				v = "-"
			}
			parts[i] = padRight(v, widths[i], p.Opt.Right)
		}
		bw.WriteString(strings.TrimRight(strings.Join(parts, " "), " "))
		bw.WriteString("\n")
	}
	return nil
}

func runeLen(s string) int { return utf8.RuneCountInString(s) }
func padRight(s string, w int, right bool) string {
	pad := w - runeLen(s)
	if pad <= 0 {
		return s
	}
	if right {
		return strings.Repeat(" ", pad) + s
	}
	return s + strings.Repeat(" ", pad)
}

// -------------------- XTAB --------------------

type XTABReader struct{ Opt *FormatOptions }

func (x *XTABReader) Read(r io.Reader, emit func(*Record) error) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 1024*1024), 1024*1024*64)
	rec := NewRecord()
	flush := func() error {
		if rec.Len() == 0 {
			return nil
		}
		err := emit(rec)
		rec = NewRecord()
		return err
	}
	for sc.Scan() {
		line := sc.Text()
		if strings.TrimSpace(line) == "" {
			if err := flush(); err != nil {
				return err
			}
			continue
		}
		i := strings.IndexAny(line, " \t")
		if i < 0 {
			rec.Set(line, "")
			continue
		}
		key := line[:i]
		rest := strings.TrimLeft(line[i:], " \t")
		rec.Set(key, rest)
	}
	if err := flush(); err != nil {
		return err
	}
	return sc.Err()
}

type XTABWriter struct{ Opt *FormatOptions }

func (x *XTABWriter) Write(w io.Writer, recs []*Record) error {
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	for i, r := range recs {
		if i > 0 {
			bw.WriteString("\n")
		}
		// Width = max key length.
		kw := 0
		for _, k := range r.Keys {
			if l := runeLen(k); l > kw {
				kw = l
			}
		}
		for j, k := range r.Keys {
			bw.WriteString(padRight(k, kw, false))
			bw.WriteString(" ")
			bw.WriteString(r.Values[j])
			bw.WriteString("\n")
		}
	}
	return nil
}

// -------------------- Markdown --------------------

type MDReader struct{ Opt *FormatOptions }

func (m *MDReader) Read(r io.Reader, emit func(*Record) error) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 1024*1024), 1024*1024*64)
	var header []string
	sawDivider := false
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			header = nil
			sawDivider = false
			continue
		}
		fields := splitMD(line)
		if header == nil {
			header = fields
			sawDivider = false
			continue
		}
		if !sawDivider {
			sawDivider = true
			continue
		}
		rec := NewRecord()
		for i, v := range fields {
			if i < len(header) {
				rec.Set(header[i], v)
			} else {
				rec.Set(strconv.Itoa(i+1), v)
			}
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
	return sc.Err()
}

func splitMD(line string) []string {
	line = strings.TrimPrefix(line, "|")
	line = strings.TrimSuffix(line, "|")
	parts := strings.Split(line, "|")
	out := make([]string, len(parts))
	for i, p := range parts {
		out[i] = strings.TrimSpace(p)
	}
	return out
}

type MDWriter struct{ Opt *FormatOptions }

func (m *MDWriter) Write(w io.Writer, recs []*Record) error {
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	groups := groupBySchema(recs)
	for gi, g := range groups {
		if gi > 0 {
			bw.WriteString("\n")
		}
		if len(g) == 0 {
			continue
		}
		keys := g[0].Keys
		bw.WriteString("| " + strings.Join(keys, " | ") + " |\n")
		dashes := make([]string, len(keys))
		for i := range keys {
			dashes[i] = "---"
		}
		bw.WriteString("| " + strings.Join(dashes, " | ") + " |\n")
		for _, r := range g {
			bw.WriteString("| " + strings.Join(r.Values, " | ") + " |\n")
		}
	}
	return nil
}

// -------------------- JSON --------------------

type JSONReader struct {
	Opt   *FormatOptions
	Lines bool
}

func (j *JSONReader) Read(r io.Reader, emit func(*Record) error) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	p := &jsonParser{data: data}
	p.skipSpace()
	if p.eof() {
		return nil
	}
	if !j.Lines && p.peek() == '[' {
		p.pos++
		p.skipSpace()
		if !p.eof() && p.peek() == ']' {
			return nil
		}
		for {
			p.skipSpace()
			v, err := p.parseValue()
			if err != nil {
				return err
			}
			obj, ok := v.(map[string][]interface{})
			_ = obj
			// We need ordered key list; handle by using the parser's record form.
			rec, ok2 := v.(*Record)
			if !ok2 {
				if r2, ok3 := toRecord(v); ok3 {
					rec = r2
				} else {
					return fmt.Errorf("expected object in JSON array")
				}
			}
			if err := emit(rec); err != nil {
				return err
			}
			p.skipSpace()
			if p.eof() {
				break
			}
			if p.peek() == ',' {
				p.pos++
				continue
			}
			if p.peek() == ']' {
				p.pos++
				break
			}
			return fmt.Errorf("unexpected character %q in JSON array", p.peek())
		}
		return nil
	}
	// JSON Lines or a single object.
	for !p.eof() {
		p.skipSpace()
		if p.eof() {
			break
		}
		v, err := p.parseValue()
		if err != nil {
			return err
		}
		rec, ok := v.(*Record)
		if !ok {
			if r2, ok2 := toRecord(v); ok2 {
				rec = r2
			} else {
				return fmt.Errorf("expected JSON object")
			}
		}
		if err := emit(rec); err != nil {
			return err
		}
	}
	return nil
}

func toRecord(v interface{}) (*Record, bool) {
	if r, ok := v.(*Record); ok {
		return r, true
	}
	return nil, false
}

type JSONWriter struct {
	Opt   *FormatOptions
	Lines bool
}

func (j *JSONWriter) Write(w io.Writer, recs []*Record) error {
	bw := bufio.NewWriter(w)
	defer bw.Flush()
	if !j.Lines {
		bw.WriteString("[\n")
		for i, r := range recs {
			if err := j.writeObjectMulti(bw, r, "", "  "); err != nil {
				return err
			}
			if i < len(recs)-1 {
				bw.WriteString(",\n")
			} else {
				bw.WriteString("\n")
			}
		}
		bw.WriteString("]\n")
		return nil
	}
	for _, r := range recs {
		if err := j.writeObjectSingle(bw, r); err != nil {
			return err
		}
		bw.WriteString("\n")
	}
	return nil
}

func (j *JSONWriter) writeObjectMulti(bw *bufio.Writer, r *Record, indent, step string) error {
	bw.WriteString(indent + "{\n")
	for i, k := range r.Keys {
		bw.WriteString(indent + step)
		writeJSONString(bw, k)
		bw.WriteString(": ")
		bw.WriteString(jsonValueFromString(r.Values[i]))
		if i < len(r.Keys)-1 {
			bw.WriteString(",")
		}
		bw.WriteString("\n")
	}
	bw.WriteString(indent + "}")
	return nil
}

func (j *JSONWriter) writeObjectSingle(bw *bufio.Writer, r *Record) error {
	bw.WriteString("{")
	for i, k := range r.Keys {
		if i > 0 {
			bw.WriteString(", ")
		}
		writeJSONString(bw, k)
		bw.WriteString(": ")
		bw.WriteString(jsonValueFromString(r.Values[i]))
	}
	bw.WriteString("}")
	return nil
}

func jsonValueFromString(s string) string {
	// Preserve JSON value classification: int, float, true/false, null, else string.
	if s == "true" || s == "false" || s == "null" {
		return s
	}
	if IsInt(s) {
		return s
	}
	if IsFloat(s) {
		return s
	}
	var buf bytes.Buffer
	writeJSONString(&buf, s)
	return buf.String()
}

func writeJSONString(w io.Writer, s string) {
	var buf bytes.Buffer
	buf.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			buf.WriteString(`\"`)
		case '\\':
			buf.WriteString(`\\`)
		case '\n':
			buf.WriteString(`\n`)
		case '\r':
			buf.WriteString(`\r`)
		case '\t':
			buf.WriteString(`\t`)
		case '\b':
			buf.WriteString(`\b`)
		case '\f':
			buf.WriteString(`\f`)
		default:
			if r < 0x20 {
				buf.WriteString(fmt.Sprintf(`\u%04x`, r))
			} else {
				buf.WriteRune(r)
			}
		}
	}
	buf.WriteByte('"')
	w.Write(buf.Bytes())
}

// Minimal JSON value parser producing ordered *Record objects.

type jsonParser struct {
	data []byte
	pos  int
}

func (p *jsonParser) eof() bool { return p.pos >= len(p.data) }
func (p *jsonParser) peek() byte {
	if p.eof() {
		return 0
	}
	return p.data[p.pos]
}
func (p *jsonParser) skipSpace() {
	for !p.eof() {
		c := p.data[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
			continue
		}
		break
	}
}
func (p *jsonParser) parseValue() (interface{}, error) {
	p.skipSpace()
	if p.eof() {
		return nil, fmt.Errorf("unexpected end of JSON")
	}
	c := p.peek()
	switch {
	case c == '{':
		return p.parseObject()
	case c == '[':
		return p.parseArray()
	case c == '"':
		return p.parseString()
	case c == 't' || c == 'f' || c == 'n':
		return p.parseLit()
	default:
		return p.parseNumber()
	}
}
func (p *jsonParser) parseObject() (*Record, error) {
	if p.peek() != '{' {
		return nil, fmt.Errorf("expected {")
	}
	p.pos++
	rec := NewRecord()
	p.skipSpace()
	if p.peek() == '}' {
		p.pos++
		return rec, nil
	}
	for {
		p.skipSpace()
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
		key := s
		p.skipSpace()
		if p.peek() != ':' {
			return nil, fmt.Errorf("expected : in object")
		}
		p.pos++
		p.skipSpace()
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		rec.Set(key, jsonRenderValue(v))
		p.skipSpace()
		if p.peek() == ',' {
			p.pos++
			continue
		}
		if p.peek() == '}' {
			p.pos++
			return rec, nil
		}
		return nil, fmt.Errorf("unexpected character %q in JSON object", p.peek())
	}
}
func (p *jsonParser) parseArray() ([]interface{}, error) {
	if p.peek() != '[' {
		return nil, fmt.Errorf("expected [")
	}
	p.pos++
	var out []interface{}
	p.skipSpace()
	if p.peek() == ']' {
		p.pos++
		return out, nil
	}
	for {
		p.skipSpace()
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		out = append(out, v)
		p.skipSpace()
		if p.peek() == ',' {
			p.pos++
			continue
		}
		if p.peek() == ']' {
			p.pos++
			return out, nil
		}
		return nil, fmt.Errorf("unexpected char in array")
	}
}
func (p *jsonParser) parseString() (string, error) {
	if p.peek() != '"' {
		return "", fmt.Errorf("expected string")
	}
	p.pos++
	var b bytes.Buffer
	for !p.eof() {
		c := p.data[p.pos]
		if c == '"' {
			p.pos++
			return b.String(), nil
		}
		if c == '\\' {
			p.pos++
			if p.eof() {
				return "", fmt.Errorf("unterminated escape")
			}
			esc := p.data[p.pos]
			p.pos++
			switch esc {
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			case '/':
				b.WriteByte('/')
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case 'n':
				b.WriteByte('\n')
			case 'r':
				b.WriteByte('\r')
			case 't':
				b.WriteByte('\t')
			case 'u':
				if p.pos+4 > len(p.data) {
					return "", fmt.Errorf("bad \\u escape")
				}
				hex := string(p.data[p.pos : p.pos+4])
				p.pos += 4
				n, err := strconv.ParseUint(hex, 16, 32)
				if err != nil {
					return "", err
				}
				b.WriteRune(rune(n))
			default:
				return "", fmt.Errorf("bad escape %c", esc)
			}
			continue
		}
		b.WriteByte(c)
		p.pos++
	}
	return "", fmt.Errorf("unterminated string")
}
func (p *jsonParser) parseLit() (interface{}, error) {
	if bytes.HasPrefix(p.data[p.pos:], []byte("true")) {
		p.pos += 4
		return true, nil
	}
	if bytes.HasPrefix(p.data[p.pos:], []byte("false")) {
		p.pos += 5
		return false, nil
	}
	if bytes.HasPrefix(p.data[p.pos:], []byte("null")) {
		p.pos += 4
		return nil, nil
	}
	return nil, fmt.Errorf("unexpected literal")
}
func (p *jsonParser) parseNumber() (interface{}, error) {
	start := p.pos
	if p.peek() == '-' || p.peek() == '+' {
		p.pos++
	}
	for !p.eof() {
		c := p.data[p.pos]
		if (c >= '0' && c <= '9') || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
			p.pos++
			continue
		}
		break
	}
	s := string(p.data[start:p.pos])
	if s == "" {
		return nil, fmt.Errorf("expected number")
	}
	if IsInt(s) {
		v, _ := strconv.ParseInt(s, 10, 64)
		return v, nil
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return nil, err
	}
	return f, nil
}

func jsonRenderValue(v interface{}) string {
	switch x := v.(type) {
	case nil:
		return ""
	case bool:
		if x {
			return "true"
		}
		return "false"
	case int64:
		return strconv.FormatInt(x, 10)
	case float64:
		return FormatFloat(x)
	case string:
		return x
	case *Record:
		// Flatten nested object to "key.subkey" placeholders using JSON serialization.
		var buf bytes.Buffer
		buf.WriteString("{")
		for i, k := range x.Keys {
			if i > 0 {
				buf.WriteString(", ")
			}
			writeJSONString(&buf, k)
			buf.WriteString(": ")
			buf.WriteString(jsonValueFromString(x.Values[i]))
		}
		buf.WriteString("}")
		return buf.String()
	case []interface{}:
		var buf bytes.Buffer
		buf.WriteString("[")
		for i, e := range x {
			if i > 0 {
				buf.WriteString(", ")
			}
			// Render each element.
			switch ev := e.(type) {
			case string:
				var sb bytes.Buffer
				writeJSONString(&sb, ev)
				buf.Write(sb.Bytes())
			default:
				buf.WriteString(jsonRenderValue(e))
			}
		}
		buf.WriteString("]")
		return buf.String()
	}
	return fmt.Sprintf("%v", v)
}

// -------------------- helpers --------------------

// sortKeysStable sorts keys preserving first occurrence order.
func sortKeysStable(ks []string) []string {
	// Not actually used: Miller preserves insertion order.
	out := append([]string(nil), ks...)
	sort.SliceStable(out, func(i, j int) bool { return out[i] < out[j] })
	return out
}
