		v.groups[key] = append(v.groups[key], rec)
		if len(v.groups[key]) > v.n {
			v.groups[key] = v.groups[key][len(v.groups[key])-v.n:]
		}
		return
	}
	v.buf = append(v.buf, rec)
	if len(v.buf) > v.n {
