	}
	if v.useRegex {
		for _, f := range v.fields {
			re, err := compileMlrRegex(f)
			if err != nil {
				return nil, nil, err
			}
			v.regexes = append(v.regexes, re)
		}
	}
	return v, nil, nil
}

func compileMlrRegex(s string) (*regexp.Regexp, error) {
	caseInsensitive := false
	if strings.HasPrefix(s, `"`) {
		// "..."i form
		if strings.HasSuffix(s, `"i`) {
			caseInsensitive = true
			s = s[1 : len(s)-2]
		} else if strings.HasSuffix(s, `"`) {
			s = s[1 : len(s)-1]
		}
	}
	if caseInsensitive {
		s = "(?i)" + s
	}
	return regexp.Compile(s)
}

// -------------------- sort --------------------

type sortKey struct {
	field     string
	numeric   bool
	descending bool
	caseFold  bool
	natural   bool
}

type sortVerb struct {
	keys []sortKey
	buf  []*Record
	moveToFront bool
}

func (v *sortVerb) Name() string { return "sort" }
func (v *sortVerb) Process(rec *Record, emit func(*Record)) { v.buf = append(v.buf, rec) }
func (v *sortVerb) Finish(emit func(*Record)) {
	sort.SliceStable(v.buf, func(i, j int) bool {
		return v.less(v.buf[i], v.buf[j])
	})
	for _, r := range v.buf {
		out := r
		if v.moveToFront {
			out = r.Copy()
			// Move sort fields to the front, preserving order.
			names := make([]string, 0, len(v.keys))
			for _, k := range v.keys {
				names = append(names, k.field)
			}
			reorderFront(out, names)
		}
		emit(out)
	}
}
func (v *sortVerb) less(a, b *Record) bool {
	for _, k := range v.keys {
		av, aok := a.Get(k.field)
		bv, bok := b.Get(k.field)
		if !aok && !bok {
			continue
		}
		if !aok {
			return false
		}
		if !bok {
			return true
		}
		var cmp int
		if k.numeric {
			if c, ok := NumericCompare(av, bv); ok {
				cmp = c
			} else {
				cmp = strings.Compare(av, bv)
			}
		} else if k.caseFold {
			cmp = strings.Compare(strings.ToLower(av), strings.ToLower(bv))
		} else if k.natural {
			cmp = naturalCompare(av, bv)
		} else {
			cmp = strings.Compare(av, bv)
		}
		if cmp != 0 {
			if k.descending {
				return cmp > 0
			}
			return cmp < 0
		}
	}
	return false
}

func reorderFront(r *Record, names []string) {
	newKeys := make([]string, 0, len(r.Keys))
	newVals := make([]string, 0, len(r.Values))
	taken := map[string]bool{}
	for _, n := range names {
		if i := indexOf(r.Keys, n); i >= 0 {
			newKeys = append(newKeys, n)
			newVals = append(newVals, r.Values[i])
			taken[n] = true
		}
	}
	for i, k := range r.Keys {
		if !taken[k] {
			newKeys = append(newKeys, k)
			newVals = append(newVals, r.Values[i])
		}
	}
	r.Keys = newKeys
	r.Values = newVals
}

func indexOf(xs []string, s string) int {
	for i, x := range xs {
		if x == s {
			return i
		}
	}
	return -1
}

func naturalCompare(a, b string) int {
	// Simple numeric-chunk aware comparison.
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if isDigit(a[i]) && isDigit(b[j]) {
			ai, an := readNum(a, i)
			bi, bn := readNum(b, j)
			if an != bn {
				if an < bn {
					return -1
				}
				return 1
			}
			for k := 0; k < (ai - i); k++ {
				if a[i+k] != b[j+k] {
					if a[i+k] < b[j+k] {
						return -1
					}
					return 1
				}
			}
			i = ai
			j = bi
			continue
		}
		if a[i] != b[j] {
			if a[i] < b[j] {
				return -1
			}
			return 1
		}
		i++
		j++
	}
	if i == len(a) && j == len(b) {
		return 0
	}
	if i == len(a) {
		return -1
	}
	return 1
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func readNum(s string, start int) (int, int64) {
	i := start
	for i < len(s) && isDigit(s[i]) {
		i++
	}
	n, _ := strconv.ParseInt(s[start:i], 10, 64)
	return i, n
}

func parseSortArgs(args []string) (*sortVerb, []string, error) {
	v := &sortVerb{}
	i := 0
	add := func(flag, names string) {
		for _, f := range parseCommaList(names) {
			k := sortKey{field: f}
			switch flag {
			case "-f":
			case "-r":
				k.descending = true
			case "-c":
				k.caseFold = true
			case "-cr":
				k.caseFold = true
				k.descending = true
			case "-n", "-nf":
				k.numeric = true
			case "-nr":
				k.numeric = true
				k.descending = true
			case "-t":
				k.natural = true
			case "-tr", "-rt":
				k.natural = true
				k.descending = true
			}
			v.keys = append(v.keys, k)
		}
	}
	for i < len(args) {
		a := args[i]
		switch a {
		case "-f", "-r", "-c", "-cr", "-n", "-nf", "-nr", "-t", "-tr", "-rt":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr sort: %s requires an argument", a)
			}
			add(a, args[i+1])
			i += 2
		case "-b":
			v.moveToFront = true
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"sort"}
		default:
			return v, args[i:], nil
		}
	}
	if len(v.keys) == 0 {
		return nil, nil, fmt.Errorf("mlr sort: -f, -r, etc., is required")
	}
	return v, nil, nil
}

// -------------------- rename --------------------

type renameVerb struct {
	pairs  [][2]string // old,new
	useRegex bool
	global bool
	regexes []*regexp.Regexp
}

func (v *renameVerb) Name() string { return "rename" }
func (v *renameVerb) Process(rec *Record, emit func(*Record)) {
	out := rec.Copy()
	for idx, p := range v.pairs {
		if v.useRegex {
			re := v.regexes[idx]
			for i, k := range out.Keys {
				var nk string
				if v.global {
					nk = re.ReplaceAllString(k, p[1])
				} else {
					loc := re.FindStringIndex(k)
					if loc == nil {
						continue
					}
					nk = k[:loc[0]] + re.ReplaceAllString(k[loc[0]:loc[1]], p[1]) + k[loc[1]:]
				}
				if nk != k {
					out.Keys[i] = nk
				}
			}
		} else {
			for i, k := range out.Keys {
				if k == p[0] {
					out.Keys[i] = p[1]
				}
			}
		}
	}
	emit(out)
}
func (v *renameVerb) Finish(emit func(*Record)) {}

func parseRenameArgs(args []string) (*renameVerb, []string, error) {
	v := &renameVerb{}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-r":
			v.useRegex = true
			i++
		case "-g":
			v.global = true
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"rename"}
		default:
			// Expect field list.
			parts := parseCommaList(a)
			if len(parts)%2 != 0 {
				return nil, nil, fmt.Errorf("mlr rename: odd number of field names")
			}
			for k := 0; k < len(parts); k += 2 {
				v.pairs = append(v.pairs, [2]string{parts[k], parts[k+1]})
				if v.useRegex {
					re, err := compileMlrRegex(parts[k])
					if err != nil {
						return nil, nil, err
					}
					v.regexes = append(v.regexes, re)
				}
			}
			i++
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

// -------------------- label --------------------

type labelVerb struct {
	names []string
}

func (v *labelVerb) Name() string { return "label" }
func (v *labelVerb) Process(rec *Record, emit func(*Record)) {
	out := rec.Copy()
	for i, n := range v.names {
		if i >= len(out.Keys) {
			break
		}
		out.Keys[i] = n
	}
	emit(out)
}
func (v *labelVerb) Finish(emit func(*Record)) {}

func parseLabelArgs(args []string) (*labelVerb, []string, error) {
	for i, a := range args {
		switch a {
		case "-h", "--help":
			return nil, nil, helpRequest{"label"}
		default:
			names := parseCommaList(a)
			return &labelVerb{names: names}, args[i+1:], nil
		}
	}
	return nil, nil, fmt.Errorf("mlr label: name list required")
}

// -------------------- uniq --------------------

type uniqVerb struct {
	groupBy   []string
	exclude   []string
	showCount bool
	numOnly   bool
	countName string
	all       bool
	seen      map[string]int
	order     []string
	firstRec  map[string]*Record
	total     int
}

func (v *uniqVerb) Name() string { return "uniq" }
func (v *uniqVerb) Process(rec *Record, emit func(*Record)) {
	var key string
	if v.all {
		key = allKeyValues(rec)
	} else if len(v.exclude) > 0 {
		key = allKeyValuesExcluding(rec, v.exclude)
	} else {
		key = keyForGroup(rec, v.groupBy)
	}
	if _, ok := v.seen[key]; !ok {
		v.order = append(v.order, key)
		v.firstRec[key] = rec.Copy()
	}
	v.seen[key]++
	v.total++
}
func (v *uniqVerb) Finish(emit func(*Record)) {
	if v.numOnly {
		out := NewRecord()
		out.Set("count", strconv.Itoa(len(v.order)))
		emit(out)
		return
	}
	for _, key := range v.order {
		if v.all {
			out := v.firstRec[key].Copy()
			if v.showCount {
				out.Prepend(v.countName, strconv.Itoa(v.seen[key]))
			}
			emit(out)
			continue
		}
		rec := v.firstRec[key]
		out := NewRecord()
		if len(v.exclude) > 0 {
			for i, k := range rec.Keys {
				skip := false
				for _, x := range v.exclude {
					if x == k {
						skip = true
						break
					}
				}
				if !skip {
					out.Set(k, rec.Values[i])
				}
			}
		} else {
			for _, f := range v.groupBy {
				if val, ok := rec.Get(f); ok {
					out.Set(f, val)
				}
			}
		}
		if v.showCount {
			out.Set(v.countName, strconv.Itoa(v.seen[key]))
		}
		emit(out)
	}
}

func allKeyValues(rec *Record) string {
	var parts []string
	for i, k := range rec.Keys {
		parts = append(parts, k+"\x01"+rec.Values[i])
	}
	return strings.Join(parts, "\x00")
}
func allKeyValuesExcluding(rec *Record, excl []string) string {
	set := make(map[string]bool)
	for _, e := range excl {
		set[e] = true
	}
	var parts []string
	for i, k := range rec.Keys {
		if set[k] {
			continue
		}
		parts = append(parts, k+"\x01"+rec.Values[i])
	}
	return strings.Join(parts, "\x00")
}

func parseUniqArgs(args []string) (*uniqVerb, []string, error) {
	v := &uniqVerb{countName: "count", seen: map[string]int{}, firstRec: map[string]*Record{}}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-g", "-f":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr uniq: %s requires an argument", a)
			}
			v.groupBy = parseCommaList(args[i+1])
			i += 2
		case "-x":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr uniq: -x requires an argument")
			}
			v.exclude = parseCommaList(args[i+1])
			i += 2
		case "-c":
			v.showCount = true
			i++
		case "-n":
			v.numOnly = true
			i++
		case "-o":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr uniq: -o requires an argument")
			}
			v.countName = args[i+1]
			i += 2
		case "-a":
			v.all = true
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"uniq"}
		default:
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

// -------------------- count --------------------

type countVerb struct {
	groupBy   []string
	numOnly   bool
	countName string
	total     int
	groups    map[string]int
	order     []string
	groupRec  map[string]*Record
}

func (v *countVerb) Name() string { return "count" }
func (v *countVerb) Process(rec *Record, emit func(*Record)) {
	v.total++
	if len(v.groupBy) > 0 {
		key := keyForGroup(rec, v.groupBy)
		if _, ok := v.groups[key]; !ok {
			v.order = append(v.order, key)
			gr := NewRecord()
			for _, f := range v.groupBy {
				val, _ := rec.Get(f)
				gr.Set(f, val)
			}
			v.groupRec[key] = gr
		}
		v.groups[key]++
	}
}
func (v *countVerb) Finish(emit func(*Record)) {
	if len(v.groupBy) == 0 {
		out := NewRecord()
		out.Set(v.countName, strconv.Itoa(v.total))
		emit(out)
		return
	}
	if v.numOnly {
		out := NewRecord()
		out.Set(v.countName, strconv.Itoa(len(v.order)))
		emit(out)
		return
	}
	for _, key := range v.order {
		out := v.groupRec[key].Copy()
		out.Set(v.countName, strconv.Itoa(v.groups[key]))
		emit(out)
	}
}

func parseCountArgs(args []string) (*countVerb, []string, error) {
	v := &countVerb{countName: "count", groups: map[string]int{}, groupRec: map[string]*Record{}}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-g":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr count: -g requires an argument")
			}
			v.groupBy = parseCommaList(args[i+1])
			i += 2
		case "-n":
			v.numOnly = true
			i++
		case "-o":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr count: -o requires an argument")
			}
			v.countName = args[i+1]
			i += 2
		case "-h", "--help":
			return nil, nil, helpRequest{"count"}
		default:
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

