// -------------------- reorder --------------------

type reorderVerb struct {
	fields []string
	toEnd  bool
}

func (v *reorderVerb) Name() string { return "reorder" }
func (v *reorderVerb) Process(rec *Record, emit func(*Record)) {
	out := rec.Copy()
	if v.toEnd {
		// Move specified fields to the end.
		names := map[string]bool{}
		for _, f := range v.fields {
			names[f] = true
		}
		// Keep non-specified fields first in their order.
		nk, nv := []string{}, []string{}
		for i, k := range out.Keys {
			if !names[k] {
				nk = append(nk, k)
				nv = append(nv, out.Values[i])
			}
		}
		for _, f := range v.fields {
			if idx := indexOf(out.Keys, f); idx >= 0 {
				nk = append(nk, f)
				nv = append(nv, out.Values[idx])
			}
		}
		out.Keys, out.Values = nk, nv
	} else {
		reorderFront(out, v.fields)
	}
	emit(out)
}
func (v *reorderVerb) Finish(emit func(*Record)) {}

func parseReorderArgs(args []string) (*reorderVerb, []string, error) {
	v := &reorderVerb{}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-f":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr reorder: -f requires an argument")
			}
			v.fields = parseCommaList(args[i+1])
			i += 2
		case "-e":
			v.toEnd = true
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"reorder"}
		default:
			return v, args[i:], nil
		}
	}
	if len(v.fields) == 0 {
		return nil, nil, fmt.Errorf("mlr reorder: -f is required")
	}
	return v, nil, nil
}

// -------------------- regularize --------------------

type regularizeVerb struct {
	seen map[string][]string
	buf  []*Record
}

func (v *regularizeVerb) Name() string { return "regularize" }
func (v *regularizeVerb) Process(rec *Record, emit func(*Record)) {
	sorted := append([]string(nil), rec.Keys...)
	sort.Strings(sorted)
	sig := strings.Join(sorted, "\x00")
	canon, ok := v.seen[sig]
	if !ok {
		v.seen[sig] = append([]string(nil), rec.Keys...)
		emit(rec)
		return
	}
	// Reorder rec to match canon.
	out := NewRecord()
	for _, k := range canon {
		val, _ := rec.Get(k)
		out.Set(k, val)
	}
	emit(out)
}
func (v *regularizeVerb) Finish(emit func(*Record)) {}

func parseRegularizeArgs(args []string) (*regularizeVerb, []string, error) {
	for i, a := range args {
		if a == "-h" || a == "--help" {
			return nil, nil, helpRequest{"regularize"}
		}
		return &regularizeVerb{seen: map[string][]string{}}, args[i:], nil
	}
	return &regularizeVerb{seen: map[string][]string{}}, nil, nil
}

// -------------------- skip-trivial-records --------------------

type skipTrivialVerb struct{}

func (v *skipTrivialVerb) Name() string { return "skip-trivial-records" }
func (v *skipTrivialVerb) Process(rec *Record, emit func(*Record)) {
	hasNonEmpty := false
	for _, val := range rec.Values {
		if val != "" {
			hasNonEmpty = true
			break
		}
	}
	if rec.Len() > 0 && hasNonEmpty {
		emit(rec)
	}
