// -------------------- cat --------------------

type catVerb struct {
	addCounter bool
	counterName string
	groupBy     []string
	groupCounts map[string]int
	counter     int
}

func (v *catVerb) Name() string { return "cat" }
func (v *catVerb) Process(rec *Record, emit func(*Record)) {
	out := rec
	if v.addCounter {
		var n int
		if len(v.groupBy) > 0 {
			key := keyForGroup(rec, v.groupBy)
			v.groupCounts[key]++
			n = v.groupCounts[key]
		} else {
			v.counter++
			n = v.counter
		}
		out = rec.Copy()
		out.Prepend(v.counterName, strconv.Itoa(n))
	}
	emit(out)
}
func (v *catVerb) Finish(emit func(*Record)) {}

func parseCatArgs(args []string) (*catVerb, []string, error) {
