type tailVerb struct {
	n       int
	groupBy []string
	buf     []*Record
	groups  map[string][]*Record
}

func (v *tailVerb) Name() string { return "tail" }
func (v *tailVerb) Process(rec *Record, emit func(*Record)) {
	if len(v.groupBy) > 0 {
		key := keyForGroup(rec, v.groupBy)
		v.groups[key] = append(v.groups[key], rec)
		if len(v.groups[key]) > v.n {
			v.groups[key] = v.groups[key][len(v.groups[key])-v.n:]
		}
		return
	}
	v.buf = append(v.buf, rec)
	if len(v.buf) > v.n {
		v.buf = v.buf[len(v.buf)-v.n:]
	}
}
func (v *tailVerb) Finish(emit func(*Record)) {
	if len(v.groupBy) > 0 {
