		// Better: maintain a separate ordered keys slice.
		for _, key := range v.groupOrder {
			for _, rec := range v.groups[key] {
				emit(rec)
			}
		}
		return
	}
	for _, rec := range v.buf {
		emit(rec)
	}
}

