type reorderVerb struct {
	fields []string
	toEnd  bool
}

func (v *reorderVerb) Name() string { return "reorder" }
func (v *reorderVerb) Process(rec *Record, emit func(*Record)) {
	out := rec.Copy()
	if v.toEnd {
		// Move specified fields to the end.
		names := map[string]bool{}
		for _, f := range v.fields {
			names[f] = true
		}
		// Keep non-specified fields first in their order.
		nk, nv := []string{}, []string{}
		for i, k := range out.Keys {
			if !names[k] {
				nk = append(nk, k)
				nv = append(nv, out.Values[i])
			}
		}
		for _, f := range v.fields {
			if idx := indexOf(out.Keys, f); idx >= 0 {
				nk = append(nk, f)
				nv = append(nv, out.Values[idx])
			}
		}
		out.Keys, out.Values = nk, nv
	} else {
		reorderFront(out, v.fields)
	}
	emit(out)
}
func (v *reorderVerb) Finish(emit func(*Record)) {}

