// -------------------- cut --------------------

type cutVerb struct {
	fields     []string
	order      bool
	complement bool
	useRegex   bool
	regexes    []*regexp.Regexp
}

func (v *cutVerb) Name() string { return "cut" }
func (v *cutVerb) Process(rec *Record, emit func(*Record)) {
	out := NewRecord()
	matcher := func(k string) bool {
		if v.useRegex {
			for _, re := range v.regexes {
				if re.MatchString(k) {
					return true
				}
			}
			return false
		}
		for _, f := range v.fields {
			if f == k {
				return true
			}
		}
		return false
	}
	if v.complement {
		for i, k := range rec.Keys {
			if !matcher(k) {
				out.Set(k, rec.Values[i])
			}
		}
	} else if v.order {
		for _, f := range v.fields {
			if val, ok := rec.Get(f); ok {
				out.Set(f, val)
			}
		}
	} else {
		for i, k := range rec.Keys {
			if matcher(k) {
				out.Set(k, rec.Values[i])
			}
		}
	}
	emit(out)
}
func (v *cutVerb) Finish(emit func(*Record)) {}

func parseCutArgs(args []string) (*cutVerb, []string, error) {
	v := &cutVerb{}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
