func (v *regularizeVerb) Process(rec *Record, emit func(*Record)) {
	sorted := append([]string(nil), rec.Keys...)
	sort.Strings(sorted)
	sig := strings.Join(sorted, "\x00")
	canon, ok := v.seen[sig]
	if !ok {
		v.seen[sig] = append([]string(nil), rec.Keys...)
		emit(rec)
		return
	}
	// Reorder rec to match canon.
	out := NewRecord()
	for _, k := range canon {
		val, _ := rec.Get(k)
		out.Set(k, val)
	}
	emit(out)
}
