package main

import (
	"fmt"
	"strconv"
	"strings"
)

// A tiny expression evaluator supporting a subset of Miller's DSL
// suitable for simple filter/put expressions used in common workflows.

type token struct {
	kind string
	val  string
}

type exprLexer struct {
	src  string
	pos  int
	toks []token
}

func lex(src string) ([]token, error) {
	l := &exprLexer{src: src}
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		switch {
		case c == ' ' || c == '\t' || c == '\n':
			l.pos++
		case c == '"':
			s, err := l.readString()
			if err != nil {
				return nil, err
			}
			l.toks = append(l.toks, token{"str", s})
		case c == '$':
			l.pos++
			start := l.pos
			for l.pos < len(l.src) && (isIdent(l.src[l.pos]) || l.src[l.pos] == '*') {
				l.pos++
			}
			l.toks = append(l.toks, token{"field", l.src[start:l.pos]})
		case c >= '0' && c <= '9':
			start := l.pos
			for l.pos < len(l.src) && (l.src[l.pos] >= '0' && l.src[l.pos] <= '9' || l.src[l.pos] == '.') {
				l.pos++
			}
			if l.pos < len(l.src) && (l.src[l.pos] == 'e' || l.src[l.pos] == 'E') {
				l.pos++
				if l.pos < len(l.src) && (l.src[l.pos] == '+' || l.src[l.pos] == '-') {
					l.pos++
				}
				for l.pos < len(l.src) && l.src[l.pos] >= '0' && l.src[l.pos] <= '9' {
					l.pos++
				}
			}
			l.toks = append(l.toks, token{"num", l.src[start:l.pos]})
		case isAlpha(c):
			start := l.pos
			for l.pos < len(l.src) && isIdent(l.src[l.pos]) {
				l.pos++
			}
			w := l.src[start:l.pos]
			switch w {
			case "true", "false":
				l.toks = append(l.toks, token{"bool", w})
			default:
				l.toks = append(l.toks, token{"ident", w})
			}
		default:
			if ok, sym := l.matchOp(); ok {
				l.toks = append(l.toks, token{"op", sym})
			} else {
				return nil, fmt.Errorf("unexpected character %q", c)
			}
		}
	}
	return l.toks, nil
}

func (l *exprLexer) matchOp() (bool, string) {
	twoChars := []string{"==", "!=", "<=", ">=", "&&", "||", "=~", "!~"}
	if l.pos+1 < len(l.src) {
		two := l.src[l.pos : l.pos+2]
		for _, op := range twoChars {
			if two == op {
				l.pos += 2
				return true, op
			}
		}
	}
	c := l.src[l.pos]
	switch c {
	case '+', '-', '*', '/', '%', '<', '>', '(', ')', ',', '=', '!':
		l.pos++
		return true, string(c)
	}
	return false, ""
}

func (l *exprLexer) readString() (string, error) {
	if l.src[l.pos] != '"' {
		return "", fmt.Errorf("expected string")
	}
	l.pos++
	var b strings.Builder
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		if c == '"' {
			l.pos++
			return b.String(), nil
		}
		if c == '\\' && l.pos+1 < len(l.src) {
			nc := l.src[l.pos+1]
			switch nc {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			default:
				b.WriteByte(nc)
			}
			l.pos += 2
			continue
		}
		b.WriteByte(c)
		l.pos++
	}
	return "", fmt.Errorf("unterminated string")
}

func isAlpha(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
}
func isIdent(c byte) bool {
	return isAlpha(c) || (c >= '0' && c <= '9')
}

type parser struct {
	toks []token
	pos  int
}

func (p *parser) peek() *token {
	if p.pos >= len(p.toks) {
		return nil
	}
	return &p.toks[p.pos]
}
func (p *parser) next() *token {
	t := p.peek()
	if t != nil {
		p.pos++
	}
	return t
}

// Expression AST node.

type node struct {
	op       string
	val      string
	children []*node
}

func (p *parser) parseExpr() (*node, error) { return p.parseOr() }
func (p *parser) parseOr() (*node, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil || t.kind != "op" || t.val != "||" {
			break
		}
		p.next()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &node{op: "||", children: []*node{left, right}}
	}
	return left, nil
}
func (p *parser) parseAnd() (*node, error) {
	left, err := p.parseEq()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil || t.kind != "op" || t.val != "&&" {
			break
		}
		p.next()
		right, err := p.parseEq()
		if err != nil {
			return nil, err
		}
		left = &node{op: "&&", children: []*node{left, right}}
	}
	return left, nil
}
func (p *parser) parseEq() (*node, error) {
	left, err := p.parseCmp()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil || t.kind != "op" {
			break
		}
		if t.val != "==" && t.val != "!=" && t.val != "=~" && t.val != "!~" {
			break
		}
		p.next()
		right, err := p.parseCmp()
		if err != nil {
			return nil, err
		}
		left = &node{op: t.val, children: []*node{left, right}}
	}
	return left, nil
}
func (p *parser) parseCmp() (*node, error) {
	left, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil || t.kind != "op" {
			break
		}
		if t.val != "<" && t.val != ">" && t.val != "<=" && t.val != ">=" {
			break
		}
		p.next()
		right, err := p.parseAdd()
		if err != nil {
			return nil, err
		}
		left = &node{op: t.val, children: []*node{left, right}}
	}
	return left, nil
}
func (p *parser) parseAdd() (*node, error) {
	left, err := p.parseMul()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil || t.kind != "op" {
			break
		}
		if t.val != "+" && t.val != "-" {
			break
		}
		p.next()
		right, err := p.parseMul()
		if err != nil {
			return nil, err
		}
		left = &node{op: t.val, children: []*node{left, right}}
	}
	return left, nil
}
func (p *parser) parseMul() (*node, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t == nil || t.kind != "op" {
			break
		}
		if t.val != "*" && t.val != "/" && t.val != "%" {
			break
		}
		p.next()
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		left = &node{op: t.val, children: []*node{left, right}}
	}
	return left, nil
}
func (p *parser) parseUnary() (*node, error) {
	t := p.peek()
	if t != nil && t.kind == "op" && (t.val == "-" || t.val == "!") {
		p.next()
		child, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &node{op: "u" + t.val, children: []*node{child}}, nil
	}
	return p.parsePrimary()
}
func (p *parser) parsePrimary() (*node, error) {
	t := p.next()
	if t == nil {
		return nil, fmt.Errorf("expected expression")
	}
	switch t.kind {
	case "num":
		return &node{op: "num", val: t.val}, nil
	case "str":
		return &node{op: "str", val: t.val}, nil
	case "bool":
		return &node{op: "bool", val: t.val}, nil
	case "field":
		return &node{op: "field", val: t.val}, nil
	case "ident":
		if p.peek() != nil && p.peek().kind == "op" && p.peek().val == "(" {
			p.next()
			var args []*node
			if p.peek() != nil && !(p.peek().kind == "op" && p.peek().val == ")") {
				for {
					a, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					args = append(args, a)
					t := p.peek()
					if t != nil && t.kind == "op" && t.val == "," {
						p.next()
						continue
					}
					break
				}
			}
			if p.peek() == nil || p.peek().val != ")" {
				return nil, fmt.Errorf("expected )")
			}
			p.next()
			return &node{op: "call", val: t.val, children: args}, nil
		}
		return &node{op: "ident", val: t.val}, nil
	case "op":
		if t.val == "(" {
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if p.peek() == nil || p.peek().val != ")" {
				return nil, fmt.Errorf("expected )")
			}
			p.next()
			return e, nil
		}
	}
	return nil, fmt.Errorf("unexpected token %q", t.val)
}

// Value type

type value struct {
	kind string // "int", "float", "str", "bool", "null"
	i    int64
	f    float64
	s    string
	b    bool
}

func valFromString(s string) value {
	if s == "" {
		return value{kind: "str", s: s}
	}
	if IsInt(s) {
		n, _ := strconv.ParseInt(s, 10, 64)
		return value{kind: "int", i: n}
	}
	if IsFloat(s) {
		f, _ := strconv.ParseFloat(s, 64)
		return value{kind: "float", f: f}
	}
	if s == "true" {
		return value{kind: "bool", b: true}
	}
	if s == "false" {
		return value{kind: "bool", b: false}
	}
	return value{kind: "str", s: s}
}

func (v value) asFloat() (float64, bool) {
	switch v.kind {
	case "int":
		return float64(v.i), true
	case "float":
		return v.f, true
	}
	return 0, false
}
func (v value) asInt() (int64, bool) {
	switch v.kind {
	case "int":
		return v.i, true
	case "float":
		return int64(v.f), true
	}
	return 0, false
}
func (v value) asStr() string {
	switch v.kind {
	case "int":
		return strconv.FormatInt(v.i, 10)
	case "float":
		return FormatFloat(v.f)
	case "str":
		return v.s
	case "bool":
		if v.b {
			return "true"
		}
		return "false"
	}
	return ""
}
func (v value) asBool() bool {
	switch v.kind {
	case "bool":
		return v.b
	case "int":
		return v.i != 0
	case "float":
		return v.f != 0
	case "str":
		return v.s != ""
	}
	return false
}

type evalCtx struct {
	rec *Record
	vars map[string]value
	nr  int
	nf  int
	filename string
}

func eval(n *node, ctx *evalCtx) (value, error) {
	switch n.op {
	case "num":
		return valFromString(n.val), nil
	case "str":
		return value{kind: "str", s: n.val}, nil
	case "bool":
		return value{kind: "bool", b: n.val == "true"}, nil
	case "field":
		if n.val == "*" {
			// Represent as a string snapshot; limited support.
			return value{kind: "str", s: ""}, nil
		}
		v, ok := ctx.rec.Get(n.val)
		if !ok {
			return value{kind: "null"}, nil
		}
		return valFromString(v), nil
	case "ident":
		switch n.val {
		case "NR":
			return value{kind: "int", i: int64(ctx.nr)}, nil
		case "NF":
			return value{kind: "int", i: int64(ctx.rec.Len())}, nil
		case "FILENAME":
			return value{kind: "str", s: ctx.filename}, nil
		case "true":
			return value{kind: "bool", b: true}, nil
		case "false":
			return value{kind: "bool", b: false}, nil
		case "M_PI":
			return value{kind: "float", f: 3.141592653589793}, nil
		case "M_E":
			return value{kind: "float", f: 2.718281828459045}, nil
		}
		if v, ok := ctx.vars[n.val]; ok {
			return v, nil
		}
		return value{kind: "null"}, nil
	case "u-":
		v, err := eval(n.children[0], ctx)
		if err != nil {
			return value{}, err
		}
		if f, ok := v.asFloat(); ok {
			if v.kind == "int" {
				return value{kind: "int", i: -v.i}, nil
			}
			return value{kind: "float", f: -f}, nil
		}
		return value{}, fmt.Errorf("cannot negate non-number")
	case "u!":
		v, err := eval(n.children[0], ctx)
		if err != nil {
			return value{}, err
		}
		return value{kind: "bool", b: !v.asBool()}, nil
	case "+", "-", "*", "/", "%":
		a, err := eval(n.children[0], ctx)
		if err != nil {
			return value{}, err
		}
		b, err := eval(n.children[1], ctx)
		if err != nil {
			return value{}, err
		}
		if n.op == "+" && (a.kind == "str" || b.kind == "str") {
			return value{kind: "str", s: a.asStr() + b.asStr()}, nil
		}
		if a.kind == "int" && b.kind == "int" && n.op != "/" {
			switch n.op {
			case "+":
				return value{kind: "int", i: a.i + b.i}, nil
			case "-":
				return value{kind: "int", i: a.i - b.i}, nil
			case "*":
				return value{kind: "int", i: a.i * b.i}, nil
			case "%":
				if b.i == 0 {
					return value{kind: "null"}, nil
				}
				return value{kind: "int", i: a.i % b.i}, nil
			}
		}
		af, aok := a.asFloat()
		bf, bok := b.asFloat()
		if !aok || !bok {
			return value{}, fmt.Errorf("non-numeric in arithmetic")
		}
		switch n.op {
		case "+":
			return floatOrInt(af + bf), nil
		case "-":
			return floatOrInt(af - bf), nil
		case "*":
			return floatOrInt(af * bf), nil
		case "/":
			if bf == 0 {
				return value{kind: "null"}, nil
			}
			return floatOrInt(af / bf), nil
		case "%":
			if bf == 0 {
				return value{kind: "null"}, nil
			}
			return value{kind: "float", f: floatMod(af, bf)}, nil
		}
	case "==", "!=", "<", ">", "<=", ">=":
		a, err := eval(n.children[0], ctx)
		if err != nil {
			return value{}, err
		}
		b, err := eval(n.children[1], ctx)
		if err != nil {
			return value{}, err
		}
		return compareVals(a, b, n.op), nil
	case "&&":
		a, err := eval(n.children[0], ctx)
		if err != nil {
			return value{}, err
		}
		if !a.asBool() {
			return value{kind: "bool", b: false}, nil
		}
		b, err := eval(n.children[1], ctx)
		if err != nil {
			return value{}, err
		}
		return value{kind: "bool", b: b.asBool()}, nil
	case "||":
		a, err := eval(n.children[0], ctx)
		if err != nil {
			return value{}, err
		}
		if a.asBool() {
			return value{kind: "bool", b: true}, nil
		}
		b, err := eval(n.children[1], ctx)
		if err != nil {
			return value{}, err
		}
		return value{kind: "bool", b: b.asBool()}, nil
	case "=~", "!~":
		a, err := eval(n.children[0], ctx)
		if err != nil {
			return value{}, err
		}
		b, err := eval(n.children[1], ctx)
		if err != nil {
			return value{}, err
		}
		return regexMatch(a.asStr(), b.asStr(), n.op == "!~")
	case "call":
		return evalCall(n, ctx)
	}
	return value{}, fmt.Errorf("unknown op %q", n.op)
}

func floatOrInt(f float64) value {
	if f == float64(int64(f)) && f > -1e15 && f < 1e15 {
		return value{kind: "int", i: int64(f)}
	}
	return value{kind: "float", f: f}
}
func floatMod(a, b float64) float64 {
	r := a - float64(int64(a/b))*b
	return r
}

func compareVals(a, b value, op string) value {
	// Numeric compare if both numeric.
	af, aok := a.asFloat()
	bf, bok := b.asFloat()
	var cmp int
	if aok && bok {
		if af < bf {
			cmp = -1
		} else if af > bf {
			cmp = 1
		} else {
			cmp = 0
		}
	} else {
		as, bs := a.asStr(), b.asStr()
		cmp = strings.Compare(as, bs)
	}
	var r bool
	switch op {
	case "==":
		r = cmp == 0
	case "!=":
		r = cmp != 0
	case "<":
		r = cmp < 0
	case ">":
		r = cmp > 0
	case "<=":
		r = cmp <= 0
	case ">=":
		r = cmp >= 0
	}
	return value{kind: "bool", b: r}
}

type filterVerb struct {
	ast     *node
	exclude bool
}

func (v *filterVerb) Name() string { return "filter" }
func (v *filterVerb) Process(rec *Record, emit func(*Record)) {
	ctx := &evalCtx{rec: rec, vars: map[string]value{}}
	r, err := eval(v.ast, ctx)
	if err != nil {
		return
	}
	keep := r.asBool()
	if v.exclude {
		keep = !keep
	}
	if keep {
		emit(rec)
	}
}
func (v *filterVerb) Finish(emit func(*Record)) {}

func parseFilterArgs(args []string) (*filterVerb, []string, error) {
	v := &filterVerb{}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-x":
			v.exclude = true
			i++
		case "-q":
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"filter"}
		default:
			expr := a
			toks, err := lex(expr)
			if err != nil {
				return nil, nil, fmt.Errorf("mlr filter: %v", err)
			}
			p := &parser{toks: toks}
			ast, err := p.parseExpr()
			if err != nil {
				return nil, nil, fmt.Errorf("mlr filter: %v", err)
			}
			v.ast = ast
			return v, args[i+1:], nil
		}
	}
	return nil, nil, fmt.Errorf("mlr filter: expression required")
}

// Put verb: $x = expr; $y = expr; ...

type putStmt struct {
	field string
	ast   *node
	del   bool
}

type putVerb struct {
	stmts []putStmt
	quiet bool
}

func (v *putVerb) Name() string { return "put" }
func (v *putVerb) Process(rec *Record, emit func(*Record)) {
	ctx := &evalCtx{rec: rec, vars: map[string]value{}}
	for _, s := range v.stmts {
		if s.del {
			rec.Delete(s.field)
			continue
		}
		val, err := eval(s.ast, ctx)
		if err != nil {
			continue
		}
		rec.Set(s.field, val.asStr())
	}
	if !v.quiet {
		emit(rec)
	}
}
func (v *putVerb) Finish(emit func(*Record)) {}

func parsePutArgs(args []string) (*putVerb, []string, error) {
	v := &putVerb{}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-q":
			v.quiet = true
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"put"}
		default:
			stmts, err := parsePutDSL(a)
			if err != nil {
				return nil, nil, fmt.Errorf("mlr put: %v", err)
			}
			v.stmts = stmts
			return v, args[i+1:], nil
		}
	}
	return nil, nil, fmt.Errorf("mlr put: expression required")
}

func parsePutDSL(src string) ([]putStmt, error) {
	// Split at ; (top level only, but no parens in simple expressions; easy case).
	var stmts []putStmt
	// Tokenize once to find `=` assignments; we support `$x = expr`.
	parts := splitTopLevel(src, ';')
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		// $field = expr
		eq := findTopLevel(p, "=")
		if eq < 0 {
			return nil, fmt.Errorf("expected $field = expression")
		}
		lhs := strings.TrimSpace(p[:eq])
		rhs := strings.TrimSpace(p[eq+1:])
		if !strings.HasPrefix(lhs, "$") {
			return nil, fmt.Errorf("lhs must be $field")
		}
		field := lhs[1:]
		toks, err := lex(rhs)
		if err != nil {
			return nil, err
		}
		ps := &parser{toks: toks}
		ast, err := ps.parseExpr()
		if err != nil {
			return nil, err
		}
		stmts = append(stmts, putStmt{field: field, ast: ast})
	}
	return stmts, nil
}

func splitTopLevel(s string, sep byte) []string {
	var parts []string
	depth := 0
	start := 0
	inStr := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '"' {
			inStr = !inStr
		}
		if inStr {
			continue
		}
		if c == '(' {
			depth++
		}
		if c == ')' {
			depth--
		}
		if depth == 0 && c == sep {
			parts = append(parts, s[start:i])
			start = i + 1
		}
	}
	parts = append(parts, s[start:])
	return parts
}
func findTopLevel(s, sub string) int {
	depth := 0
	inStr := false
	for i := 0; i+len(sub) <= len(s); i++ {
		c := s[i]
		if c == '"' {
			inStr = !inStr
		}
		if inStr {
			continue
		}
		if c == '(' {
			depth++
		}
		if c == ')' {
			depth--
		}
		if depth == 0 {
			if s[i] == '=' && (i+1 >= len(s) || (s[i+1] != '=' && s[i+1] != '~')) {
				if i > 0 && (s[i-1] == '<' || s[i-1] == '>' || s[i-1] == '!' || s[i-1] == '=') {
					continue
				}
				return i
			}
		}
	}
	return -1
}
