		}
		return value{kind: "float", f: f}, nil
	case "string":
		return value{kind: "str", s: args[0].asStr()}, nil
	case "asserting_int":
		if args[0].kind != "int" {
			return value{}, fmt.Errorf("not int")
		}
		return args[0], nil
	}
