func reduce(args []value, fn func(a, b float64) float64) value {
	if len(args) == 0 {
		return value{kind: "null"}
	}
	out, _ := args[0].asFloat()
	for _, a := range args[1:] {
		f, _ := a.asFloat()
		out = fn(out, f)
	}
	return value{kind: "float", f: out}
}

func regexMatch(s, pattern string, negate bool) (value, error) {
	re, err := regexp.Compile(pattern)
	if err != nil {
		return value{}, err
	}
	m := re.MatchString(s)
	if negate {
		m = !m
	}
	return value{kind: "bool", b: m}, nil
}
