// -------------------- clean-whitespace --------------------

type cleanWSVerb struct {
	onlyKeys   bool
	onlyValues bool
}

func (v *cleanWSVerb) Name() string { return "clean-whitespace" }
func (v *cleanWSVerb) Process(rec *Record, emit func(*Record)) {
	out := rec.Copy()
	for i := range out.Keys {
		if !v.onlyValues {
			out.Keys[i] = cleanWS(out.Keys[i])
		}
		if !v.onlyKeys {
			out.Values[i] = cleanWS(out.Values[i])
		}
	}
	emit(out)
}
func (v *cleanWSVerb) Finish(emit func(*Record)) {}

func cleanWS(s string) string {
	s = strings.TrimSpace(s)
	// Collapse internal runs of whitespace to a single space.
	var b strings.Builder
	lastSpace := false
	for _, r := range s {
		if r == ' ' || r == '\t' {
			if !lastSpace {
				b.WriteByte(' ')
				lastSpace = true
			}
		} else {
			b.WriteRune(r)
			lastSpace = false
		}
	}
	return b.String()
}

func parseCleanWSArgs(args []string) (*cleanWSVerb, []string, error) {
	v := &cleanWSVerb{}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-k":
			v.onlyKeys = true
			i++
		case "-v":
			v.onlyValues = true
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"clean-whitespace"}
		default:
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

// -------------------- remove-empty-columns --------------------

type remEmptyColsVerb struct {
	buf []*Record
}

func (v *remEmptyColsVerb) Name() string { return "remove-empty-columns" }
func (v *remEmptyColsVerb) Process(rec *Record, emit func(*Record)) {
	v.buf = append(v.buf, rec)
}
func (v *remEmptyColsVerb) Finish(emit func(*Record)) {
	// Find columns that are ever non-empty.
	nonEmpty := map[string]bool{}
	for _, r := range v.buf {
		for i, k := range r.Keys {
			if r.Values[i] != "" {
				nonEmpty[k] = true
			}
		}
	}
	for _, r := range v.buf {
		out := NewRecord()
		for i, k := range r.Keys {
			if nonEmpty[k] {
				out.Set(k, r.Values[i])
			}
		}
		emit(out)
	}
}

func parseRemEmptyColsArgs(args []string) (*remEmptyColsVerb, []string, error) {
	for i, a := range args {
		if a == "-h" || a == "--help" {
			return nil, nil, helpRequest{"remove-empty-columns"}
		}
		return &remEmptyColsVerb{}, args[i:], nil
	}
	return &remEmptyColsVerb{}, nil, nil
}

// -------------------- fill-down --------------------

type fillDownVerb struct {
	fields   []string
	all      bool
	onlyIfEmpty bool
	prev     map[string]string
}

func (v *fillDownVerb) Name() string { return "fill-down" }
func (v *fillDownVerb) Process(rec *Record, emit func(*Record)) {
	out := rec.Copy()
	names := v.fields
	if v.all {
		names = out.Keys
	}
	for _, f := range names {
		cur, present := out.Get(f)
		if !present || cur == "" {
			if prev, ok := v.prev[f]; ok {
				out.Set(f, prev)
			}
		} else {
			v.prev[f] = cur
		}
	}
	emit(out)
}
func (v *fillDownVerb) Finish(emit func(*Record)) {}

func parseFillDownArgs(args []string) (*fillDownVerb, []string, error) {
	v := &fillDownVerb{prev: map[string]string{}}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-f":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr fill-down: -f requires an argument")
			}
			v.fields = parseCommaList(args[i+1])
			i += 2
		case "-a", "--all":
			v.all = true
			i++
		case "--only-if-blank", "-b":
			v.onlyIfEmpty = true
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"fill-down"}
		default:
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

// -------------------- fill-empty --------------------

type fillEmptyVerb struct {
	fill string
}

func (v *fillEmptyVerb) Name() string { return "fill-empty" }
func (v *fillEmptyVerb) Process(rec *Record, emit func(*Record)) {
	out := rec.Copy()
	for i, val := range out.Values {
		if val == "" {
			out.Values[i] = v.fill
		}
	}
	emit(out)
}
func (v *fillEmptyVerb) Finish(emit func(*Record)) {}

func parseFillEmptyArgs(args []string) (*fillEmptyVerb, []string, error) {
	v := &fillEmptyVerb{fill: "N/A"}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-v":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr fill-empty: -v requires an argument")
			}
			v.fill = args[i+1]
			i += 2
		case "-h", "--help":
			return nil, nil, helpRequest{"fill-empty"}
		case "--only-if-all-empty":
			i++
		case "-S":
			i++
		default:
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

// -------------------- group-like --------------------

type groupLikeVerb struct {
	groups map[string][]*Record
	order  []string
}

func (v *groupLikeVerb) Name() string { return "group-like" }
func (v *groupLikeVerb) Process(rec *Record, emit func(*Record)) {
	key := strings.Join(rec.Keys, "\x00")
	if _, ok := v.groups[key]; !ok {
		v.order = append(v.order, key)
	}
	v.groups[key] = append(v.groups[key], rec)
}
func (v *groupLikeVerb) Finish(emit func(*Record)) {
	for _, k := range v.order {
		for _, r := range v.groups[k] {
			emit(r)
		}
	}
}

func parseGroupLikeArgs(args []string) (*groupLikeVerb, []string, error) {
	for i, a := range args {
		if a == "-h" || a == "--help" {
			return nil, nil, helpRequest{"group-like"}
		}
		return &groupLikeVerb{groups: map[string][]*Record{}}, args[i:], nil
	}
	return &groupLikeVerb{groups: map[string][]*Record{}}, nil, nil
}

// -------------------- having-fields --------------------

type havingFieldsVerb struct {
	mode string   // all-defined, any-defined, all-matching, any-matching, etc.
	fields []string
	regexes []*regexp.Regexp
}

func (v *havingFieldsVerb) Name() string { return "having-fields" }
func (v *havingFieldsVerb) Process(rec *Record, emit func(*Record)) {
	keep := false
	switch v.mode {
	case "all-defined":
		keep = true
		for _, f := range v.fields {
			if _, ok := rec.Get(f); !ok {
				keep = false
				break
			}
		}
	case "any-defined":
		for _, f := range v.fields {
			if _, ok := rec.Get(f); ok {
				keep = true
				break
			}
		}
	case "all-matching":
		keep = true
		for _, f := range v.fields {
			found := false
			for _, k := range rec.Keys {
				if k == f {
					found = true
					break
				}
			}
			if !found {
				keep = false
				break
			}
		}
	case "any-matching":
		for _, re := range v.regexes {
			for _, k := range rec.Keys {
				if re.MatchString(k) {
					keep = true
					break
				}
			}
			if keep {
				break
			}
		}
	}
	if keep {
		emit(rec)
	}
}
func (v *havingFieldsVerb) Finish(emit func(*Record)) {}

func parseHavingFieldsArgs(args []string) (*havingFieldsVerb, []string, error) {
	v := &havingFieldsVerb{}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "--all-defined":
			v.mode = "all-defined"
			if i+1 < len(args) {
				v.fields = parseCommaList(args[i+1])
				i++
			}
			i++
		case "--any-defined":
			v.mode = "any-defined"
			if i+1 < len(args) {
				v.fields = parseCommaList(args[i+1])
				i++
			}
			i++
		case "-h", "--help":
			return nil, nil, helpRequest{"having-fields"}
		default:
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}

