// -------------------- stats1 --------------------

type stats1Acc struct {
	count int
	sum   float64
	sum2  float64
	min   float64
	max   float64
	haveMin bool
	values []float64 // for median/percentile/etc.
	strs    []string // for mode/distinct counts on strings
	nonNumCount int
}

type stats1Verb struct {
	accNames []string
	fields   []string
	groupBy  []string
	order    []string
	groups   map[string]*Record
	groupAccs map[string]map[string]*stats1Acc // group -> "field_stat" -> acc
	fieldsSet []string
}

func (v *stats1Verb) Name() string { return "stats1" }
func (v *stats1Verb) Process(rec *Record, emit func(*Record)) {
	key := keyForGroup(rec, v.groupBy)
	if _, ok := v.groupAccs[key]; !ok {
		v.order = append(v.order, key)
		v.groupAccs[key] = map[string]*stats1Acc{}
		gr := NewRecord()
		for _, f := range v.groupBy {
			val, _ := rec.Get(f)
			gr.Set(f, val)
		}
		v.groups[key] = gr
	}
	accs := v.groupAccs[key]
	for _, f := range v.fields {
		val, ok := rec.Get(f)
		if !ok {
			continue
		}
		fl, err := strconv.ParseFloat(val, 64)
		isNum := err == nil
		for _, a := range v.accNames {
			key2 := f + "_" + a
			acc, ok := accs[key2]
			if !ok {
				acc = &stats1Acc{}
				accs[key2] = acc
			}
			if isNum {
				acc.count++
				acc.sum += fl
				acc.sum2 += fl * fl
				if !acc.haveMin || fl < acc.min {
					acc.min = fl
					acc.haveMin = true
				}
				if acc.count == 1 || fl > acc.max {
					acc.max = fl
				}
				acc.values = append(acc.values, fl)
			} else {
				acc.nonNumCount++
				acc.strs = append(acc.strs, val)
			}
		}
	}
}
func (v *stats1Verb) Finish(emit func(*Record)) {
	for _, key := range v.order {
		out := v.groups[key].Copy()
		accs := v.groupAccs[key]
		for _, f := range v.fields {
			for _, a := range v.accNames {
				accKey := f + "_" + a
				acc := accs[accKey]
				if acc == nil {
					continue
				}
				out.Set(accKey, stats1Format(a, acc))
			}
		}
		emit(out)
	}
}

func stats1Format(name string, acc *stats1Acc) string {
	switch name {
	case "count":
		return strconv.Itoa(acc.count + acc.nonNumCount)
	case "sum":
		return trimNum(acc.sum)
	case "min":
		if !acc.haveMin && len(acc.strs) > 0 {
			min := acc.strs[0]
			for _, s := range acc.strs[1:] {
				if s < min {
					min = s
				}
			}
			return min
		}
		return trimNum(acc.min)
	case "max":
		if acc.count == 0 && len(acc.strs) > 0 {
			max := acc.strs[0]
			for _, s := range acc.strs[1:] {
				if s > max {
					max = s
				}
			}
			return max
		}
		return trimNum(acc.max)
	case "mean":
		if acc.count == 0 {
			return ""
		}
		return trimNum(acc.sum / float64(acc.count))
	case "var":
		if acc.count < 2 {
			return ""
		}
		m := acc.sum / float64(acc.count)
		return trimNum((acc.sum2 - float64(acc.count)*m*m) / float64(acc.count-1))
	case "stddev":
		if acc.count < 2 {
			return ""
		}
		m := acc.sum / float64(acc.count)
		return trimNum(sqrtFloat((acc.sum2 - float64(acc.count)*m*m) / float64(acc.count-1)))
	case "meaneb":
		if acc.count < 2 {
			return ""
		}
		m := acc.sum / float64(acc.count)
		sd := sqrtFloat((acc.sum2 - float64(acc.count)*m*m) / float64(acc.count-1))
		return trimNum(sd / sqrtFloat(float64(acc.count)))
	case "median":
		if acc.count == 0 {
			return ""
		}
		vs := append([]float64(nil), acc.values...)
		sort.Float64s(vs)
		mid := len(vs) / 2
		if len(vs)%2 == 1 {
			return trimNum(vs[mid])
		}
		return trimNum((vs[mid-1] + vs[mid]) / 2)
	case "first":
		if acc.count > 0 {
			return trimNum(acc.values[0])
		}
		if len(acc.strs) > 0 {
			return acc.strs[0]
		}
		return ""
	case "last":
		if acc.count > 0 {
			return trimNum(acc.values[len(acc.values)-1])
		}
		if len(acc.strs) > 0 {
			return acc.strs[len(acc.strs)-1]
		}
		return ""
	case "range":
		if acc.haveMin {
			return trimNum(acc.max - acc.min)
		}
		return ""
	case "distinct_count":
		set := map[string]bool{}
		for _, v := range acc.values {
			set[trimNum(v)] = true
		}
		for _, s := range acc.strs {
			set[s] = true
		}
		return strconv.Itoa(len(set))
	case "null_count":
		return "0"
	case "distinct_sum":
		set := map[float64]bool{}
		for _, v := range acc.values {
			set[v] = true
		}
		sum := 0.0
		for v := range set {
			sum += v
		}
		return trimNum(sum)
	}
	return ""
}

func trimNum(f float64) string { return FormatFloat(f) }

func sqrtFloat(f float64) float64 {
	if f < 0 {
		return 0
	}
	return sqrtNewton(f)
}
func sqrtNewton(x float64) float64 {
	if x == 0 {
		return 0
	}
	g := x
	for i := 0; i < 40; i++ {
		g = 0.5 * (g + x/g)
	}
	return g
}

func parseStats1Args(args []string) (*stats1Verb, []string, error) {
	v := &stats1Verb{groups: map[string]*Record{}, groupAccs: map[string]map[string]*stats1Acc{}}
	i := 0
	for i < len(args) {
		a := args[i]
		switch a {
		case "-a":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr stats1: -a requires an argument")
			}
			v.accNames = parseCommaList(args[i+1])
			i += 2
		case "-f":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr stats1: -f requires an argument")
			}
			v.fields = parseCommaList(args[i+1])
			i += 2
		case "-g":
			if i+1 >= len(args) {
				return nil, nil, fmt.Errorf("mlr stats1: -g requires an argument")
			}
			v.groupBy = parseCommaList(args[i+1])
			i += 2
		case "-s":
			i++
		case "--fr", "--gr":
			i += 2
		case "-F":
			i += 2
		case "-h", "--help":
			return nil, nil, helpRequest{"stats1"}
		default:
			return v, args[i:], nil
		}
	}
	return v, nil, nil
}
