	// Preserve JSON value classification: int, float, true/false, null, else string.
	if s == "true" || s == "false" || s == "null" {
		return s
	}
	if IsInt(s) {
		return s
	}
	if IsFloat(s) {
		return s
	}
	// Nested containers: if the value looks like a JSON object/array AND parses, emit raw.
	if len(s) > 0 && (s[0] == '{' || s[0] == '[') {
		if isValidJSONContainer(s) {
			return s
		}
	}
	var buf bytes.Buffer
	writeJSONString(&buf, s)
	return buf.String()
}

func isValidJSONContainer(s string) bool {
	p := &jsonParser{data: []byte(s)}
	p.skipSpace()
	if p.eof() {
		return false
	}
	c := p.peek()
	if c != '{' && c != '[' {
		return false
	}
	_, err := p.parseValue()
	if err != nil {
		return false
	}
	p.skipSpace()
	return p.eof()
}"""
s = s.replace(old, new)

